import { defineConfig } from "vitest/config"
import { fileURLToPath } from "node:url"
import config from "../vitest.config.ts"

// Focused fixture regression gate; whole-app coverage stays unchanged in vitest.config.ts.
export default defineConfig({
  ...config,
  test: {
    ...config.test,
    include: ["db/TestSchemas.test.ts", "db/TestDatabase.test.ts", "db/Database.test.ts"],
    coverage: {
      ...config.test!.coverage,
      allowExternal: true,
      include: [
        fileURLToPath(new URL("../../../packages/repo-targets/test-utils/test-schemas.ts", import.meta.url)),
        fileURLToPath(new URL("../../../packages/smithers/flows/database/src/TestSchemas.ts", import.meta.url)),
        "db/TestDatabase.ts",
      ],
      // Cross-package paths keep this gate limited to the fixture implementation.
      exclude: [],
      reporter: ["text", "json"],
    },
  },
})

import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { defineConfig } from "vitest/config"

// `pnpm eval`: the agent evals (docs/features/agent-evals.md). They call the real model through ChatApi's metered
// endpoint and spend tokens, so `pnpm test` never runs them.
export default defineConfig({
  root: fileURLToPath(new URL("..", import.meta.url)),
  plugins: [vibelang()],
  test: {
    globalSetup: [fileURLToPath(new URL("../../../packages/repo-targets/test-utils/test-schemas.ts", import.meta.url))],
    include: ["evals/*.eval.{ts,vibe}"],
    environment: "node",
    // A whole suite runs inside one test: up to 37 agent answers in turn, each a few model calls, and a pause of a
    // minute before each trial its model failed (evals/suite.ts).
    testTimeout: 120 * 60_000,
    hookTimeout: 120_000,
  },
})

{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "strict": true,
    "noEmit": true,
    "skipLibCheck": true,
    // Alchemy follows ChatApi into the generated-view presentation components.
    "jsx": "react-jsx",
    // DOM next to workers-types: the Smithers packages these files compile from source are typed against DOM's
    // globals (`globalThis.crypto`, `TextDecoder` options), which workerd provides and workers-types declares narrower.
    "lib": [
      "ES2022",
      "DOM",
      "DOM.Iterable"
    ],
    // alchemy.run.ts and infra/ run in Node when Alchemy plans and deploys.
    "types": [
      "@cloudflare/workers-types",
      "node"
    ],
    "allowImportingTsExtensions": true
  },
  "include": [
    ".",
    "../alchemy.run.ts",
    "../ops/database"
  ]
}

import { defineConfig } from "vitest/config"

// These CLI/TLS tests own their dependencies; they don't migrate the app's database or need Electric.
export default defineConfig({
  test: {
    include: ["ops/database/*.test.ts"],
    environment: "node",
    testTimeout: 30_000,
    hookTimeout: 30_000,
  },
})

import { defineConfig, type PlaywrightTestConfig } from "@playwright/test"
// Workspace packages export their source, which can hold `.vibe` modules (an e2e spec that imports
// @smthrs/integrations reaches @smthrs/errors'). Playwright's own transform leaves them to VibeLang's loader (`build`
// below): this process registers it here, and every worker inherits it through NODE_OPTIONS.
import "vibelang/register"
import { baseURL, onThisMachine, sessionFiles, target } from "./e2e/target"
import { assertShipPrerequisites, shipAcceptance } from "./e2e/ship"

// Also protect direct Playwright invocations; prod.mjs checks earlier, before taking the test-account lock.
assertShipPrerequisites(process.env, process.argv.slice(3))

const VIBELANG_LOADER = "--import=vibelang/register"
if (!(process.env.NODE_OPTIONS ?? "").includes(VIBELANG_LOADER)) {
  process.env.NODE_OPTIONS = `${process.env.NODE_OPTIONS ?? ""} ${VIBELANG_LOADER}`.trim()
}

// Real browsers against the real app, Worker, Durable Object and model: no mocks. The target is local by default:
// Playwright starts `alchemy dev` (which needs the chat model's credential, CEREBRAS_API_KEY by default, in the
// environment). BASE_URL points the tests at a deployment, and `pnpm e2e:prod` at production (e2e/target.ts,
// docs/infrastructure.md#against-a-deployment). Locally the tests open the dev server over HTTPS and HTTP/2
// (dev/https.ts), as production serves the app.

// The dev server on this machine, on whatever port: its certificate may be self-signed (dev/https.ts).
const devCertificate = onThisMachine(baseURL)

// Node's switch for skipping TLS checks reaches every request of every worker, so a run off this machine refuses it.
if (process.env.NODE_TLS_REJECT_UNAUTHORIZED === "0") {
  if (!devCertificate) throw new Error("NODE_TLS_REJECT_UNAUTHORIZED=0 turns off TLS checks: refusing to run against a deployment")
  delete process.env.NODE_TLS_REJECT_UNAUTHORIZED
}

// Every test records its page at the size it renders, a laptop's window, 1:1: `pnpm e2e:gifs` never zooms or crops it
// (Will, 2026-10-20: "video is too zoomed in"). e2e/devices.ts opens each device at the same size.
const viewport = { width: 1280, height: 800 }

/**
 * Against a deployment: the setup signs the test account in once (e2e/deployment/sign-in.setup.ts), every test starts
 * from that session, and the run's results, summary and recordings go to their own folder, apart from a local run's.
 * One worker (the personal-model specs change the shared account) and no retries: production's model and Electric are shared, and a durable retry is the app's job.
 */
const deployment = (): PlaywrightTestConfig => {
  // When the run began, for the spend guard (e2e/spend.ts): set once here, inherited by every worker.
  process.env.E2E_RUN_STARTED_AT ??= String(Date.now())
  const outputDir = process.env.E2E_OUTPUT_DIR ?? "test-results-deployment"
  return {
    outputDir,
    workers: 1,
    retries: 0,
    timeout: 180_000,
    reporter: [["list"], ["json", { outputFile: `${outputDir}/results.json` }], ["./e2e/reporter.ts"]],
    projects: [
      // GitHub's pages stay out of every artifact: the setup records neither video nor trace.
      { name: "deployment-auth", testMatch: /deployment\/[^/]+\.setup\.ts$/, use: { video: "off", trace: "off" } },
      // No traces: a trace holds the requests' cookies, the session among them. Videos, screenshots and logs remain.
      { name: "webkit", dependencies: ["deployment-auth"], use: { browserName: "webkit", storageState: sessionFiles(baseURL).session, trace: "off" } },
      { name: "deployment", dependencies: ["deployment-auth"], use: { storageState: sessionFiles(baseURL).session, trace: "off" } },
    ],
  }
}

/** The specs whose scripted agent answers in the local shared conversation and waits for its turn there. */
const TAKES_TURNS = [
  "answer-ordering", "coedit", "factory", "files", "forms", "generated-view", "model-quota", "notifications", "pin-message",
  "queue", "repo-in-chat", "run-credentials", "run-graph", "sandbox-tools", "status", "sync", "timeline", "timeline-look", "toast-overlap",
  "todos",
].map((name) => `**/${name}.spec.ts`)

export default defineConfig({
  forbidOnly: shipAcceptance(process.env) || process.env.E2E_SHIP_COLLECT === "1",
  testDir: "e2e",
  // `.vibe` modules go to VibeLang's loader, not Playwright's TypeScript transform.
  build: { external: ["**/*.vibe"] },
  // Only specs: e2e/*.test.ts are the e2e scripts' unit tests, which vitest runs.
  testMatch: "**/*.spec.ts",
  timeout: 90_000,
  use: {
    baseURL,
    viewport,
    video: { mode: "on", size: viewport },
    trace: "retain-on-failure",
    // A machine whose browsers don't trust its dev certificate, such as one without mkcert, made a self-signed one
    // (docs/infrastructure.md#https-and-http2). The flag, not only `ignoreHTTPSErrors`, lets the service worker
    // register over it. Off this machine, the project checks every certificate.
    ignoreHTTPSErrors: devCertificate,
    launchOptions: { args: devCertificate ? ["--ignore-certificate-errors"] : [] },
  },
  ...(target === "deployment"
    ? deployment()
    : {
      projects: [
        // The dev server's sandbox limits for its one person (e2e/local/sandbox-limits.setup.ts).
        { name: "local-setup", testMatch: /local\/[^/]+\.setup\.ts$/, use: { video: "off", trace: "off" } },
        { name: "webkit", dependencies: ["local-setup"], use: { browserName: "webkit" }, workers: 1 },
        { name: "local", dependencies: ["local-setup"], testIgnore: TAKES_TURNS },
        // Locally every spec asks in one shared conversation, which answers one question at a time (worker/Answers.ts):
        // specs whose scripted agent waits for its answer, or for its person, take turns instead of timing out behind
        // each other's runs.
        { name: "local-turns", dependencies: ["local-setup"], testMatch: TAKES_TURNS, workers: 1 },
      ],
    }),
  webServer: process.env.BASE_URL
    ? undefined
    : { command: "pnpm dev", url: baseURL, ignoreHTTPSErrors: devCertificate, reuseExistingServer: true, timeout: 120_000 },
})

import { defineConfig } from "@playwright/test"
import base from "./playwright.config"

// Background progress (decision 0124) in both real engines: the normal target, sign-in, fault declarations, watchers
// and recordings, with only the three progress specs, in Chromium and WebKit.
const setup = base.projects!.filter((project) => project.name === "deployment-auth" || project.name === "local-setup")
const target = base.projects!.find((project) => project.name === "deployment" || project.name === "local")!
export default defineConfig({
  ...base,
  projects: [
    ...setup,
    ...(["chromium", "webkit"] as const).map((browserName) => ({
      name: `progress-${browserName}`,
      dependencies: setup.map((project) => project.name!),
      testMatch: /(?:background|issue|todo)-progress\.spec\.ts$/,
      use: { ...target.use, browserName },
    })),
  ],
})

import { Config, Schema } from "effect"
import { COMMAND_LIMIT_SECONDS } from "./contract"

// The deployment's sandbox settings that its Worker and its build both read (decision 0088: a program's configuration
// is captured when it is built), so the browser's tools state the limits ChatApi holds their calls to. Only Effect
// here, so the build's own config (vite.config.ts) can import it.

/**
 * `SANDBOX_COMMAND_MAX_SECONDS`: the longest command a person or an agent may run on a branch's machine, in whole
 * seconds from 60 (what a command that names no timeout runs, `SandboxTools.limits.defaultTimeoutSeconds`) to
 * `COMMAND_LIMIT_SECONDS`, the job's own limit, which it is unless set. Any other value fails with a `ConfigError`.
 * ChatApi reads it once for `POST /api/sandbox/calls`, the `FlowExecution` object once for the TODO agent's tool, and
 * the build once for the browser's run tool (src/features/sandbox/flows.ts `COMMAND_MAX_SECONDS`), so a value the
 * Worker would refuse fails the build.
 */
export const commandMaxSeconds: Config.Config<number> = Config.schema(
  Schema.Int.check(Schema.isBetween({ minimum: 60, maximum: COMMAND_LIMIT_SECONDS })),
  "SANDBOX_COMMAND_MAX_SECONDS",
).pipe(Config.withDefault(COMMAND_LIMIT_SECONDS))

import { join } from "node:path"
import react from "@vitejs/plugin-react"
import { ConfigProvider, Effect } from "effect"
import vibelang from "vibelang-vite"
import { defineConfig } from "vite"
import { VitePWA } from "vite-plugin-pwa"
import { buildOf, smithersBuild } from "./dev/build.ts"
import { devHttps } from "./dev/https.ts"
import { commandMaxSeconds } from "./src/features/sandbox/config.ts"
import { DOCS_SITE, FRAME_POLICY, PAGE_HEADERS, shellCaches } from "./src/pwa.ts"

// The app's shell, for the service worker to precache: everything a reload needs before it reaches the network.
const SHELL = ["**/*.{js,css,html,woff2,svg,png,wasm}"]

// Never the service worker's: ChatApi, the Electric shape proxy, the telemetry relay and the model endpoint.
const API = /^\/api\//

// The deployment's longest command, from the environment its Worker deploys from and read as the Worker reads it
// (decision 0088): the browser's run tool states it (src/features/sandbox/flows.ts `COMMAND_MAX_SECONDS`). The app and
// ChatApi deploy together from one environment, and a value the Worker would refuse fails the build here.
const COMMAND_MAX_SECONDS = Effect.runSync(commandMaxSeconds.parse(ConfigProvider.fromEnv()))

// Alchemy injects the Cloudflare plugin, which runs worker/index.ts beside the app in dev and build.
export default defineConfig(({ command }) => ({
  plugins: [
    // A workspace package exports its source, so the app and worker/index.ts can import `.vibe` modules; each compiles
    // with its own package's tsconfig.
    vibelang(),
    // The app's pages refuse to be framed under the dev server too, as public/_headers has Cloudflare serve them
    // (src/pwa.ts PAGE_HEADERS). Cloudflare's Vite plugin skips _headers in dev, so this sets them on every response
    // before any other middleware answers.
    {
      name: "smithers-page-headers",
      enforce: "pre",
      configureServer: (server) => {
        server.middlewares.use((_request, response, next) => {
          for (const [name, value] of Object.entries(PAGE_HEADERS)) response.setHeader(name, value)
          next()
        })
      },
    },
    react(),
    // The build's name, from the deployed revision: in the bundle for bug reports, and in /version.json (dev/build.ts).
    smithersBuild(buildOf(process.env, import.meta.dirname)),
    // The dev server over HTTPS and HTTP/2 at https://localhost:1443, as Cloudflare serves the app (dev/https.ts,
    // docs/infrastructure.md#https-and-http2). Its certificate is this machine's, kept beside the dev service worker.
    devHttps(join(import.meta.dirname, "node_modules", ".dev-https")),
    // The app is a PWA (docs/decisions/0011-the-agent-runs-in-the-browser.md §5): installable, and its service worker
    // serves the shell offline after one online visit (0002 §8). The service worker only serves files; it never runs
    // the flow engine, and never caches or answers /api/*.
    VitePWA({
      registerType: "autoUpdate",
      // main.tsx imports the virtual registration module so an activated update reloads open tabs.
      // Keep auto injection: with autoUpdate this also enables skipWaiting and clientsClaim in the generated worker.
      injectRegister: "auto",
      // The shell's glob already lists the icons.
      includeManifestIcons: false,
      manifest: {
        name: "Smithers",
        short_name: "Smithers",
        start_url: "/app",
        scope: "/",
        display: "standalone",
        background_color: "#f7f6f1",
        theme_color: "#3a756b",
        icons: [
          { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
          { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
          { src: "/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
          { src: "/icon.svg", sizes: "any", type: "image/svg+xml" },
        ],
      },
      workbox: {
        // Dev caches only its explicit shell plus modules fetched at runtime. Never precache stale generator files.
        globPatterns: command === "serve" ? [] : SHELL,
        // The language server's worker and TypeScript's lib files (src/features/code-intel/language.worker.ts) load
        // only when a TypeScript or JavaScript file first shows; the runtime cache below keeps them once they have.
        globIgnores: ["**/language.worker-*.js", "**/lib.*.d-*.js"],
        // The app's bundle and the engine worker are each over Workbox's 2 MiB default (2.7 and 2.3 MB on
        // 2026-10-20), which fails `vite build`; an offline reload needs both precached.
        maximumFileSizeToCacheInBytes: 8 * 1024 * 1024,
        navigateFallback: "index.html",
        // The docs site answers its own paths on the app's hostname (infra/DocsSite.ts); the shell never stands in.
        navigateFallbackDenylist: [API, DOCS_SITE],
        cleanupOutdatedCaches: true,
        // A module the precache doesn't list (under the dev server, every one) is kept from the last visit, so an
        // offline reload still has it. The network answers first whenever it can.
        runtimeCaching: [
          {
            // Never an embedded page: another origin's, which this worker never sees (src/pwa.ts).
            urlPattern: shellCaches,
            handler: "NetworkFirst",
            options: { cacheName: "smithers-shell", networkTimeoutSeconds: 3 },
          },
        ],
      },
      devOptions: {
        enabled: true,
        type: "module",
        navigateFallback: "index.html",
        // Every app route falls back to the shell offline, as in production; /api/* and the docs site's paths never do.
        navigateFallbackAllowlist: [new RegExp(`^(?!${API.source.slice(1)}|${DOCS_SITE.source.slice(1)})`)],
        // The dev service worker is generated here, outside the source tree.
        resolveTempFolder: () => join(import.meta.dirname, "node_modules", ".vite-pwa-dev"),
      },
    }),
    // The first paint's shell (src/firstPaint/shell.ts): src/firstPaint/inline.ts bundled into one inline script at the
    // top of `<body>`, so a cold issue page's or issues list's read starts as the document parses, before the app's
    // bundle loads. Inline, it costs no request of its own.
    {
      name: "smithers-first-paint",
      transformIndexHtml: async () => {
        const { build } = await import("esbuild")
        const built = await build({
          entryPoints: [join(import.meta.dirname, "src", "firstPaint", "inline.ts")],
          bundle: true,
          write: false,
          format: "iife",
          minify: command === "build",
          target: "es2022",
          platform: "browser",
        })
        return [{ tag: "script", children: built.outputFiles[0]!.text, injectTo: "body-prepend" }]
      },
    },
    // What the app frames: only https: pages (src/pwa.ts FRAME_POLICY), in every build.
    {
      name: "smithers-frame-policy",
      transformIndexHtml: () => [
        {
          tag: "meta",
          attrs: { "http-equiv": "Content-Security-Policy", content: FRAME_POLICY },
          injectTo: "head-prepend",
        },
      ],
    },
  ],
  define: { "globalThis.__SANDBOX_COMMAND_MAX_SECONDS__": JSON.stringify(COMMAND_MAX_SECONDS) },
  worker: { format: "es" },
  // TypeScript is the language server worker's one CommonJS import: bundled up front, so the first TypeScript file the
  // dev server shows doesn't reload every page to optimize it.
  optimizeDeps: { include: ["typescript"] },
  // The dev server transforms the app's entry and its workers' as it starts, so a dependency a change newly imports, such
  // as a new `effect/*` module, is optimized before the first page loads instead of reloading every open page (Vite's
  // "optimized dependencies changed. reloading", which answers 504 to the modules the pages were still loading).
  server: {
    // The built-PWA offline relay forwards this reserved hostname to the real API.
    allowedHosts: ["smithers.test"],
    port: 5190,
    strictPort: true,
    fs: { strict: true },
    warmup: { clientFiles: ["./src/main.tsx", "./src/flows/engine.worker.ts", "./src/features/code-intel/language.worker.ts"] },
  },
  build: { target: "esnext" },
}))

import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { defineConfig } from "vitest/config"

// Unit tests in Node: the browser's framework-free chat layer (src/), ChatApi's handlers (worker/) and the database
// (db/), against the compose Postgres and Electric (`pnpm db:up`). View regressions in tests/ use a DOM environment;
// Playwright covers real browsers. The coverage gate measures logic: every src/**/*.ts but tests and their hosts.
export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.json" })],
  test: {
    globalSetup: [
      fileURLToPath(new URL("../../packages/repo-targets/test-utils/test-schemas.ts", import.meta.url)),
      fileURLToPath(new URL("../../packages/repo-targets/test-utils/coverage-teardown.mjs", import.meta.url)),
      fileURLToPath(new URL("../../packages/repo-targets/test-utils/test-process-environment.mjs", import.meta.url)),
      // A fresh Electric replication connection for the run (db/ElectricReplication.ts).
      fileURLToPath(new URL("./db/electricReplication.globalSetup.ts", import.meta.url)),
      fileURLToPath(new URL("./worker/test/sandboxImage.globalSetup.ts", import.meta.url))
    ],
    include: [
      "PACKAGE.test.ts",
      "tests/**/*.test.{ts,vibe}",
      "src/**/*.test.{ts,vibe}",
      // The built-in plugins' tabs (decision 0017, plugins/<id>/src/tab.ts).
      "plugins/**/*.test.{ts,vibe}",
      "worker/**/*.test.{ts,vibe}",
      "db/**/*.test.{ts,vibe}",
      "infra/**/*.test.{ts,vibe}",
      "evals/**/*.test.{ts,vibe}",
      // The e2e media scripts' pure parts (e2e/frames.ts); Playwright runs only e2e/*.spec.ts.
      "e2e/**/*.test.{ts,vibe}",
      // The dev server's HTTPS and HTTP/2 front (dev/https.ts).
      "dev/**/*.test.{ts,vibe}",
      // Dashboards as code (ops/grafana/README.md) against the telemetry contract.
      "ops/**/*.test.{ts,vibe}"
    ],
    environment: "node",
    // Each file owns a four-connection SQL pool and may open flow/handler pools too. Bound file concurrency
    // below the owned fixture's 100-connection capacity, with CPU room for Electric in a shared mini farm slot.
    maxWorkers: 3,
    // A finite budget that survives coverage-instrumented load, so a genuine hang still fails the run.
    testTimeout: 30_000,
    hookTimeout: 30_000,
    coverage: {
      enabled: true,
      // Keep the coverage gate visible even when a behavioral test fails.
      reportOnFailure: true,
      provider: "v8",
      reportsDirectory: join(tmpdir(), `mvp-coverage-${process.pid}`),
      include: [
        "ops/database/Connection.ts",
        "ops/database/Policy.ts",
        "ops/database/Probe.ts",
        "src/**/*.{ts,vibe}",
        "plugins/*/src/**/*.ts",
        // Production's hostname and the docs site's routes on it (docs/infrastructure.md#domain).
        "infra/Domain.ts",
        // Remote flows (docs/features/remote-flows.md). worker/Executions.ts, the Alchemy Durable Object declaration,
        // runs only under Alchemy's bundle, so the workerd test proves it through ExecutionHost.ts instead.
        "worker/ExecutionHost.ts",
        "worker/index.ts",
        "worker/ci/*.ts",
        "worker/flows/**/*.{ts,vibe}",
        // External agents on runners (docs/features/agent-runners.md): their routes, store and Admin writes.
        "worker/runners/*.ts",
        // The metered model endpoint and admin/SetModel (docs/features/model-endpoint.md).
        "worker/Pins.ts",
        "db/migrations/0054_message_pins.ts",
        // The timeline's summaries, once per message (docs/features/timeline.md#cost).
        "worker/TimelineSummaries.ts",
        "db/migrations/0066_timeline_summaries.ts",
        "db/migrations/0075_timeline_phases.ts",
        "worker/Actor.ts",
        "worker/ErrorCode.ts",
        "worker/ModelEndpoint.ts",
        "worker/ModelRefusal.ts",
        "db/migrations/0059_model_quota_failure.ts",
        "worker/ModelRoles.ts",
        "worker/ModelUsage.ts",
        "worker/SetModel.ts",
        "worker/HostedModel.ts",
        "db/migrations/0004_model_roles.ts",
        "db/migrations/0057_model_usage_outcome.ts",
        "db/migrations/0058_hosted_model.ts",
        "db/migrations/0055_branch_ref_namespace.ts",
        // Sign-in (docs/features/sign-in.md).
        "worker/GitHubAuth.ts",
        "worker/SessionKeys.ts",
        "worker/SessionStore.ts",
        "worker/RunCredentials.ts",
        "worker/SignIn.ts",
        "db/migrations/0005_sign_in.ts",
        // Remote flow starts and the browser agent's answer routes (docs/features/remote-flows.md and agent.md).
        "worker/Answers.ts",
        "worker/Body.ts",
        "worker/Flows.ts",
        "db/migrations/0006_answer_parts.ts",
        // ChatApi stops answering: the browser's agent answers (docs/features/agent.md).
        "db/migrations/0008_browser_answering.ts",
        // Repositories: RepoApi, cloning into Code Storage and its spend (docs/features/repo.md).
        "worker/RepoApi.ts",
        "worker/RepoConfig.ts",
        "worker/RepoMetrics.ts",
        "worker/RepoReads.ts",
        "worker/Repos.ts",
        "worker/RepoUpstream.ts",
        "db/migrations/0007_repositories.ts",
        // A clone attempt's own id (docs/features/repo.md#the-clone).
        "db/migrations/0009_clone_ids.ts",
        // What GitHub says of a repository, the clone in its asker's feed, and the reclaim mark (docs/features/repo.md).
        "worker/RepoAbout.ts",
        "worker/about/*.ts",
        "db/migrations/0060_repo_about.ts",
        "db/migrations/0098_about_claim_generation.ts",
        "worker/CloneFeed.ts",
        "db/migrations/0028_clone_progress.ts",
        // Who asked each question, which the answer routes require (docs/features/agent.md#the-answer-routes).
        "worker/Messages.ts",
        "db/migrations/0011_question_askers.ts",
